 4	public final class MergeSort {
 5	
 6	    private MergeSort() {
 7	    }
 8	
 9	    /**
10	     * Sorts the provided array in place. Null and single-element arrays are left unchanged.
11	     */
12	    public static void sort(int[] values) {
13	        if (values == null || values.length < 2) {
14	            return;
15	        }
16	
17	        int[] buffer = new int[values.length];
18	        mergeSort(values, buffer, 0, values.length);
19	    }
20	
21	    private static void mergeSort(int[] values, int[] buffer, int start, int endExclusive) {
22	        if (endExclusive - start < 2) {
23	            return;
24	        }
25	
26	        int split = start + (endExclusive - start) / 2;
27	
28	        mergeSort(values, buffer, start, split);
29	        mergeSort(values, buffer, split, endExclusive);
30	
31	        if (isOrderedAcrossBoundary(values, split)) {
32	            return;
33	        }
34	
35	        merge(values, buffer, start, split, endExclusive);
36	    }
37	
38	    private static boolean isOrderedAcrossBoundary(int[] values, int split) {
39	        return values[split - 1] <= values[split];
40	    }
41	
42	    private static void merge(int[] values, int[] buffer, int start, int split, int endExclusive) {
43	        System.arraycopy(values, start, buffer, start, endExclusive - start);
44	
45	        int leftIndex = start;
46	        int rightIndex = split;
47	        int mergedIndex = start;
48	
49	        while (leftIndex < split && rightIndex < endExclusive) {
50	            if (buffer[leftIndex] <= buffer[rightIndex]) {
51	                values[mergedIndex++] = buffer[leftIndex++];
52	            } else {
53	                values[mergedIndex++] = buffer[rightIndex++];
54	            }
55	        }
56	
57	        while (leftIndex < split) {
58	            values[mergedIndex++] = buffer[leftIndex++];
59	        }
60	    }
